window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d541ccf781ab8ab7"]={"versions": [{"id": "FIG-d541ccf781ab8ab7", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung des Metamodell-Ausschnitts für das Blueprint-Konzept im Rahmen der AUTOSAR-Standardisierungsvorlage (TPS Standardization Template). Das Diagramm definiert die abstrakte Zuordnungsstruktur zwischen einer Blueprint-Spezifikation und dem daraus abgeleiteten Modellelement sowie die organisatorische Kapselung in Zuordnungsmengen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ARElement</strong>: Übergeordnete Metamodell-Basisklasse für exportierbare Top-Level-Elemente.\n</li><li><strong>BlueprintMapping::BlueprintMappingSet</strong>: Konkretes AUTOSAR-Element (<code>ARElement</code>), das als Aggregationsbehälter fungiert. Es besitzt eine Kompositionsbeziehung <code>+blueprintMap</code> mit Multiplizität <code>0..*</code> zu <code>AtpBlueprintMapping</code>.\n</li><li><strong>AtpBlueprintMapping</strong>: Abstrakte Assoziationsklasse (<code>«atpAbstract»</code>), welche die Verknüpfung zwischen Blueprint und Realisierung herstellt. Sie referenziert über die gerichtete Assoziation <code>+/atpBlueprint</code> genau eine Blueprint-Instanz (<code>1</code>) und über <code>+/atpBlueprintedElement</code> genau ein abgeleitetes Element (<code>1</code>).\n</li><li><strong>AtpBlueprint</strong>: Abstrakte Schnittstelle / Rolle (<code>«atpAbstract,atpUriDef»</code>, spezialisiert <code>Identifiable</code>), die das Quell-Element des Blueprints repräsentiert.\n</li><li><strong>AtpBlueprintable</strong>: Abstrakte Schnittstelle / Rolle (<code>«atpAbstract»</code>, spezialisiert <code>Identifiable</code>), die ein Element darstellt, das aus einem Blueprint abgeleitet werden kann.\n</li><li><strong>Identifiable</strong>: Abstrakte Basisklasse für identifizierbare Metamodell-Elemente mit Kurznamen (<code>shortName</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen oder Laufzeitsequenzen. Die Modellierungssemantik definiert zur Entwurfs- bzw. Standardisierungszeit die eindeutige Zuordnung (<code>AtpBlueprintMapping</code>) einer konkreten Vorlage (<code>AtpBlueprint</code>) zu einem ausprägenden Artefakt (<code>AtpBlueprintable</code>) innerhalb eines zentral verwalteten Sets (<code>BlueprintMappingSet</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klassen <code>AtpBlueprintMapping</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code> sind abstrakte Metamodellkonzepte (<code>atp</code> = AUTOSAR Template Pattern), die für spezifische Modellierungsdomänen durch konkrete Metaklassen spezialisiert werden müssen. Das Stereotyp <code>«atpUriDef»</code> an <code>AtpBlueprint</code> signalisiert, dass Blueprints referenzierbar über kanonische URIs identifiziert werden. Die Rollennamen <code>+/atpBlueprint</code> und <code>+/atpBlueprintedElement</code> sind als abgeleitete Assoziationsenden deklariert. Der Namensraum-Präfix <code>BlueprintMapping::</code> kennzeichnet die organisatorische Paketierung des Mapping-Sets.</p>"}, {"id": "FIG-f52eabb89021ee0c", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung des Metamodell-Ausschnitts für das Blueprint-Konzept im Rahmen der AUTOSAR-Standardisierungsvorlage (TPS Standardization Template). Das Diagramm definiert die abstrakte Zuordnungsstruktur zwischen einer Blueprint-Spezifikation und dem daraus abgeleiteten Modellelement sowie die organisatorische Kapselung in Zuordnungsmengen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ARElement</strong>: Übergeordnete Metamodell-Basisklasse für exportierbare Top-Level-Elemente.\n</li><li><strong>BlueprintMappingSet</strong>: Konkretes AUTOSAR-Element (<code>ARElement</code>), das als Aggregationsbehälter fungiert. Es besitzt eine Kompositionsbeziehung <code>+blueprintMap</code> mit Multiplizität <code>0..*</code> zu <code>AtpBlueprintMapping</code>.\n</li><li><strong>AtpBlueprintMapping</strong>: Abstrakte Assoziationsklasse (<code>«atpAbstract»</code>), welche die Verknüpfung zwischen Blueprint und Realisierung herstellt. Sie referenziert über die gerichtete Assoziation <code>+/atpBlueprint</code> genau eine Blueprint-Instanz (<code>1</code>) und über <code>+/atpBlueprintedElement</code> genau ein abgeleitetes Element (<code>1</code>).\n</li><li><strong>AtpBlueprint</strong>: Abstrakte Schnittstelle / Rolle (<code>«atpAbstract,atpUriDef»</code>, spezialisiert <code>Identifiable</code>), die das Quell-Element des Blueprints repräsentiert.\n</li><li><strong>AtpBlueprintable</strong>: Abstrakte Schnittstelle / Rolle (<code>«atpAbstract»</code>, spezialisiert <code>Identifiable</code>), die ein Element darstellt, das aus einem Blueprint abgeleitet werden kann.\n</li><li><strong>Identifiable</strong>: Abstrakte Basisklasse für identifizierbare Metamodell-Elemente mit Kurznamen (<code>shortName</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen oder Laufzeitsequenzen. Die Modellierungssemantik definiert zur Entwurfs- bzw. Standardisierungszeit die eindeutige Zuordnung (<code>AtpBlueprintMapping</code>) einer konkreten Vorlage (<code>AtpBlueprint</code>) zu einem ausprägenden Artefakt (<code>AtpBlueprintable</code>) innerhalb eines zentral verwalteten Sets (<code>BlueprintMappingSet</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Klassen <code>AtpBlueprintMapping</code>, <code>AtpBlueprint</code> und <code>AtpBlueprintable</code> sind abstrakte Metamodellkonzepte (<code>atp</code> = AUTOSAR Template Pattern), die für spezifische Modellierungsdomänen durch konkrete Metaklassen spezialisiert werden müssen. Das Stereotyp <code>«atpUriDef»</code> an <code>AtpBlueprint</code> signalisiert, dass Blueprints referenzierbar über kanonische URIs identifiziert werden. Die Rollennamen <code>+/atpBlueprint</code> und <code>+/atpBlueprintedElement</code> sind als abgeleitete Assoziationsenden deklariert. <code>BlueprintMappingSet</code> wird ohne Paketpräfix geführt.</p>"}, {"id": "FIG-77db9281efcebade", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung des Metamodell-Ausschnitts für das Blueprint-Konzept im Rahmen der AUTOSAR-Standardisierungsvorlage (TPS Standardization Template). Das Diagramm definiert die abstrakte Zuordnungsstruktur zwischen einer Blueprint-Spezifikation und dem daraus abgeleiteten Modellelement sowie die formalen Richtlinien (Blueprint Policies) zur Modifizierbarkeit und Ausprägung von Attributen bei der Ableitung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ARElement</strong>: Metamodell-Basisklasse für Top-Level-Elemente.\n</li><li><strong>BlueprintMappingSet</strong>: Konkretes <code>ARElement</code>, das über die Komposition <code>+blueprintMap</code> (<code>0..*</code>) Zuordnungen des Typs <code>AtpBlueprintMapping</code> bündelt.\n</li><li><strong>AtpBlueprintMapping</strong>: Abstrakte Assoziationsklasse, die über <code>+/atpBlueprint</code> (<code>1</code>) ein <code>AtpBlueprint</code> und über <code>+/atpBlueprintedElement</code> (<code>1</code>) ein <code>AtpBlueprintable</code> referenziert.\n</li><li><strong>AtpBlueprintable</strong>: Abstrakte Zielklasse (<code>«atpAbstract»</code>, spezialisiert <code>Identifiable</code>) eines abgeleiteten Modellelements.\n</li><li><strong>AtpBlueprint</strong>: Abstrakte Quellklasse (<code>«atpAbstract,atpUriDef»</code>, spezialisiert <code>Identifiable</code>) für Blueprints. Besitzt eine Kompositionsbeziehung <code>+blueprintPolicy</code> mit Multiplizität <code>0..*</code> zu <code>BlueprintPolicy</code>.\n</li><li><strong>BlueprintPolicy</strong>: Abstrakte Basisklasse für Blueprint-Richtlinien mit dem Attribut <code>+ attributeName :String</code>. Spezialisiert durch <code>BlueprintPolicyModifiable</code> und <code>BlueprintPolicyNotModifiable</code>.\n</li><li><strong>BlueprintPolicyNotModifiable</strong>: Konkrete Ausprägung von <code>BlueprintPolicy</code> zur Festlegung nicht-veränderbarer Vorgaben ohne zusätzliche Attribute.\n</li><li><strong>BlueprintPolicyModifiable</strong>: Abstrakte Spezialisierung von <code>BlueprintPolicy</code> für anpassbare Blueprint-Vorgaben. Besitzt eine Kompositionsbeziehung <code>+blueprintDerivationGuide</code> mit Multiplizität <code>0..1</code> zu <code>DocumentationBlock</code>.\n</li><li><strong>DocumentationBlock</strong>: Dokumentationsbaustein (<code>«atpMixed»</code>) zur textuellen Anleitung der Elementableitung.\n</li><li><strong>BlueprintPolicySingle</strong>: Konkrete Ausprägung von <code>BlueprintPolicyModifiable</code> für singuläre Attribute/Elemente.\n</li><li><strong>BlueprintPolicyList</strong>: Konkrete Ausprägung von <code>BlueprintPolicyModifiable</code> für Listenattribute. Enthält die variablen Attribute <code>+ maxNumberOfElements :PositiveInteger</code> und <code>+ minNumberOfElements :PositiveInteger</code> unter dem Stereotyp <code>«atpVariation»</code>.\n</li><li><strong>Identifiable</strong>: Abstrakte Metaklasse für identifizierbare Elemente.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen oder Laufzeitsequenzen. Die Modellierungssemantik definiert zur Entwurfs- bzw. Standardisierungszeit die eindeutige Zuordnung (<code>AtpBlueprintMapping</code>) einer konkreten Vorlage (<code>AtpBlueprint</code>) zu einem ausprägenden Artefakt (<code>AtpBlueprintable</code>) innerhalb eines zentral verwalteten Sets (<code>BlueprintMappingSet</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Blueprint-Richtlinien steuern normativ die Freiheitsgrade bei der Ausprägung konkreter Modellelemente aus Blueprints:</p>\n<ul class=\"fig-list\"><li><code>BlueprintPolicyNotModifiable</code> verbietet jegliche Abweichung vom vorgegebenen Attributwert.\n</li><li><code>BlueprintPolicyModifiable</code> erlaubt Anpassungen; über <code>blueprintDerivationGuide</code> (<code>DocumentationBlock</code>, <code>«atpMixed»</code>) kann ein erläuternder Richtlinientext hinterlegt werden.\n</li><li><code>BlueprintPolicyList</code> gestattet die Steuerung von Listenfeldern über Multiplizitätsgrenzen (<code>minNumberOfElements</code>, <code>maxNumberOfElements</code>), die dem Stereotyp <code>«atpVariation»</code> unterliegen und somit variabel gebunden werden können.\n</li><li>Die Adressierung des betroffenen Modellelement-Attributs erfolgt über <code>attributeName: String</code>.\n</li><li><code>+/atpBlueprint</code> und <code>+/atpBlueprintedElement</code> sind abgeleitete Assoziationen, <code>AtpBlueprint</code> ist per kanonischer URI adressierbar (<code>«atpUriDef»</code>).\n</li></ul>"}, {"id": "FIG-1b195e000a209bc1", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung des Metamodell-Ausschnitts für das Blueprint-Konzept im Rahmen der AUTOSAR-Standardisierungsvorlage (TPS Standardization Template). Das Diagramm definiert die abstrakte Zuordnungsstruktur zwischen einer Blueprint-Spezifikation und dem daraus abgeleiteten Modellelement sowie die formalen Richtlinien (Blueprint Policies) zur Modifizierbarkeit und Ausprägung von Attributen bei der Ableitung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ARElement</strong>: Metamodell-Basisklasse für Top-Level-Elemente.\n</li><li><strong>BlueprintMappingSet</strong>: Konkretes <code>ARElement</code>, das über die Komposition <code>+blueprintMap</code> (<code>0..*</code>) Zuordnungen des Typs <code>AtpBlueprintMapping</code> bündelt.\n</li><li><strong>AtpBlueprintMapping</strong>: Abstrakte Assoziationsklasse, die über <code>+/atpBlueprint</code> (<code>1</code>) ein <code>AtpBlueprint</code> und über <code>+/atpBlueprintedElement</code> (<code>1</code>) ein <code>AtpBlueprintable</code> referenziert.\n</li><li><strong>AtpBlueprintable</strong>: Abstrakte Zielklasse (<code>«atpAbstract»</code>, spezialisiert <code>Identifiable</code>) eines abgeleiteten Modellelements.\n</li><li><strong>AtpBlueprint</strong>: Abstrakte Quellklasse (<code>«atpAbstract,atpUriDef»</code>, spezialisiert <code>Identifiable</code>) für Blueprints. Besitzt eine Kompositionsbeziehung <code>+blueprintPolicy</code> mit Multiplizität <code>0..*</code> zu <code>BlueprintPolicy</code>.\n</li><li><strong>BlueprintPolicy</strong>: Abstrakte Basisklasse für Blueprint-Richtlinien mit dem Attribut <code>+ attributeName :String</code>. Spezialisiert durch <code>BlueprintPolicyModifiable</code> und <code>BlueprintPolicyNotModifiable</code>.\n</li><li><strong>BlueprintPolicyNotModifiable</strong>: Konkrete Ausprägung von <code>BlueprintPolicy</code> zur Festlegung nicht-veränderbarer Vorgaben ohne zusätzliche Attribute.\n</li><li><strong>BlueprintPolicyModifiable</strong>: Abstrakte Spezialisierung von <code>BlueprintPolicy</code> für anpassbare Blueprint-Vorgaben. Besitzt eine Kompositionsbeziehung <code>+blueprintDerivationGuide</code> mit Multiplizität <code>0..1</code> zu <code>DocumentationBlock</code>.\n</li><li><strong>DocumentationBlock</strong>: Dokumentationsbaustein (<code>«atpMixed»</code>) zur textuellen Anleitung der Elementableitung.\n</li><li><strong>BlueprintPolicySingle</strong>: Konkrete Ausprägung von <code>BlueprintPolicyModifiable</code> für singuläre Attribute/Elemente.\n</li><li><strong>BlueprintPolicyList</strong>: Konkrete Ausprägung von <code>BlueprintPolicyModifiable</code> für Listenattribute. Enthält die variablen Attribute <code>+ maxNumberOfElements :PositiveInteger</code> und <code>+ minNumberOfElements :PositiveInteger</code> unter dem Stereotyp <code>«atpVariation»</code>.\n</li><li><strong>Identifiable</strong>: Abstrakte Metaklasse für identifizierbare Elemente.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen oder Laufzeitsequenzen. Die Modellierungssemantik definiert zur Entwurfs- bzw. Standardisierungszeit die eindeutige Zuordnung (<code>AtpBlueprintMapping</code>) einer konkreten Vorlage (<code>AtpBlueprint</code>) zu einem ausprägenden Artefakt (<code>AtpBlueprintable</code>) innerhalb eines zentral verwalteten Sets (<code>BlueprintMappingSet</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Blueprint-Richtlinien steuern normativ die Freiheitsgrade bei der Ausprägung konkreter Modellelemente aus Blueprints:</p>\n<ul class=\"fig-list\"><li><code>BlueprintPolicyNotModifiable</code> verbietet jegliche Abweichung vom vorgegebenen Attributwert.\n</li><li><code>BlueprintPolicyModifiable</code> erlaubt Anpassungen; über <code>blueprintDerivationGuide</code> (<code>DocumentationBlock</code>, <code>«atpMixed»</code>) kann ein erläuternder Richtlinientext hinterlegt werden.\n</li><li><code>BlueprintPolicyList</code> gestattet die Steuerung von Listenfeldern über Multiplizitätsgrenzen (<code>minNumberOfElements</code>, <code>maxNumberOfElements</code>), die dem Stereotyp <code>«atpVariation»</code> unterliegen und somit variabel gebunden werden können.\n</li><li>Die Adressierung des betroffenen Modellelement-Attributs erfolgt über <code>attributeName: String</code>.\n</li><li><code>+/atpBlueprint</code> und <code>+/atpBlueprintedElement</code> sind abgeleitete Assoziationen, <code>AtpBlueprint</code> ist per kanonischer URI adressierbar (<code>«atpUriDef»</code>).\n</li></ul>"}, {"id": "FIG-398e1c7587220dde", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung des Metamodell-Ausschnitts für das Blueprint-Konzept im Rahmen der AUTOSAR-Standardisierungsvorlage (TPS Standardization Template). Das Diagramm definiert die abstrakte Zuordnungsstruktur zwischen einer Blueprint-Spezifikation und dem daraus abgeleiteten Modellelement sowie die formalen Richtlinien (Blueprint Policies) zur Modifizierbarkeit und Ausprägung von Attributen bei der Ableitung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ARElement</strong>: Metamodell-Basisklasse für Top-Level-Elemente.\n</li><li><strong>BlueprintMappingSet</strong>: Konkretes <code>ARElement</code>, das über die Komposition <code>+blueprintMap</code> (<code>0..*</code>) Zuordnungen des Typs <code>AtpBlueprintMapping</code> bündelt.\n</li><li><strong>AtpBlueprintMapping</strong>: Abstrakte Assoziationsklasse, die über <code>+/atpBlueprint</code> (<code>1</code>) ein <code>AtpBlueprint</code> und über <code>+/atpBlueprintedElement</code> (<code>1</code>) ein <code>AtpBlueprintable</code> referenziert.\n</li><li><strong>AtpBlueprintable</strong>: Abstrakte Zielklasse (<code>«atpAbstract»</code>, spezialisiert <code>Identifiable</code>) eines abgeleiteten Modellelements.\n</li><li><strong>AtpBlueprint</strong>: Abstrakte Quellklasse (<code>«atpAbstract,atpUriDef»</code>, spezialisiert <code>Identifiable</code>) für Blueprints. Besitzt eine Kompositionsbeziehung <code>+blueprintPolicy</code> mit Multiplizität <code>0..*</code> zu <code>BlueprintPolicy</code>.\n</li><li><strong>BlueprintPolicy</strong>: Abstrakte Basisklasse für Blueprint-Richtlinien mit dem Attribut <code>+ attributeName: String</code>. Spezialisiert durch <code>BlueprintPolicyModifiable</code> und <code>BlueprintPolicyNotModifiable</code>.\n</li><li><strong>BlueprintPolicyNotModifiable</strong>: Konkrete Ausprägung von <code>BlueprintPolicy</code> zur Festlegung nicht-veränderbarer Vorgaben ohne zusätzliche Attribute.\n</li><li><strong>BlueprintPolicyModifiable</strong>: Abstrakte Spezialisierung von <code>BlueprintPolicy</code> für anpassbare Blueprint-Vorgaben. Besitzt eine Kompositionsbeziehung <code>+blueprintDerivationGuide</code> mit Multiplizität <code>0..1</code> zu <code>DocumentationBlock</code>.\n</li><li><strong>DocumentationBlock</strong>: Dokumentationsbaustein (<code>«atpMixed»</code>) zur textuellen Anleitung der Elementableitung.\n</li><li><strong>BlueprintPolicySingle</strong>: Konkrete Ausprägung von <code>BlueprintPolicyModifiable</code> für singuläre Attribute/Elemente.\n</li><li><strong>BlueprintPolicyList</strong>: Konkrete Ausprägung von <code>BlueprintPolicyModifiable</code> für Listenattribute. Enthält die variablen Attribute <code>+ maxNumberOfElements: PositiveInteger</code> und <code>+ minNumberOfElements: PositiveInteger</code> unter dem Stereotyp <code>«atpVariation»</code>.\n</li><li><strong>Identifiable</strong>: Abstrakte Metaklasse für identifizierbare Elemente.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen oder Laufzeitsequenzen. Die Modellierungssemantik definiert zur Entwurfs- bzw. Standardisierungszeit die eindeutige Zuordnung (<code>AtpBlueprintMapping</code>) einer konkreten Vorlage (<code>AtpBlueprint</code>) zu einem ausprägenden Artefakt (<code>AtpBlueprintable</code>) innerhalb eines zentral verwalteten Sets (<code>BlueprintMappingSet</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Blueprint-Richtlinien steuern normativ die Freiheitsgrade bei der Ausprägung konkreter Modellelemente aus Blueprints:</p>\n<ul class=\"fig-list\"><li><code>BlueprintPolicyNotModifiable</code> verbietet jegliche Abweichung vom vorgegebenen Attributwert.\n</li><li><code>BlueprintPolicyModifiable</code> erlaubt Anpassungen; über <code>blueprintDerivationGuide</code> (<code>DocumentationBlock</code>, <code>«atpMixed»</code>) kann ein erläuternder Richtlinientext hinterlegt werden.\n</li><li><code>BlueprintPolicyList</code> gestattet die Steuerung von Listenfeldern über Multiplizitätsgrenzen (<code>minNumberOfElements</code>, <code>maxNumberOfElements</code>), die dem Stereotyp <code>«atpVariation»</code> unterliegen und somit variabel gebunden werden können.\n</li><li>Die Adressierung des betroffenen Modellelement-Attributs erfolgt über <code>attributeName: String</code>.\n</li><li><code>+/atpBlueprint</code> und <code>+/atpBlueprintedElement</code> sind abgeleitete Assoziationen, <code>AtpBlueprint</code> ist per kanonischer URI adressierbar (<code>«atpUriDef»</code>).\n</li></ul>"}, {"id": "FIG-f39c76eaed77697b", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Darstellung des Metamodell-Ausschnitts für das Blueprint-Konzept im Rahmen der AUTOSAR-Standardisierungsvorlage (TPS Standardization Template). Das Diagramm definiert die abstrakte Zuordnungsstruktur zwischen einer Blueprint-Spezifikation und dem daraus abgeleiteten Modellelement sowie die formalen Richtlinien (Blueprint Policies) zur Modifizierbarkeit und Ausprägung von Attributen bei der Ableitung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ARElement</strong>: Metamodell-Basisklasse für Top-Level-Elemente.\n</li><li><strong>BlueprintMappingSet</strong>: Konkretes <code>ARElement</code>, das über die Komposition <code>+blueprintMap</code> (<code>0..*</code>) Zuordnungen des Typs <code>AtpBlueprintMapping</code> bündelt.\n</li><li><strong>AtpBlueprintMapping</strong>: Abstrakte Assoziationsklasse, die über <code>+/atpBlueprint</code> (<code>1</code>) ein <code>AtpBlueprint</code> und über <code>+/atpBlueprintedElement</code> (<code>1</code>) ein <code>AtpBlueprintable</code> referenziert.\n</li><li><strong>AtpBlueprintable</strong>: Abstrakte Zielklasse (<code>«atpAbstract»</code>, spezialisiert <code>Identifiable</code>) eines abgeleiteten Modellelements.\n</li><li><strong>AtpBlueprint</strong>: Abstrakte Quellklasse (<code>«atpAbstract,atpUriDef»</code>, spezialisiert <code>Identifiable</code>) für Blueprints. Besitzt eine Kompositionsbeziehung <code>+blueprintPolicy</code> mit Multiplizität <code>0..*</code> zu <code>BlueprintPolicy</code>.\n</li><li><strong>BlueprintPolicy</strong>: Abstrakte Basisklasse für Blueprint-Richtlinien mit dem Attribut <code>+ attributeName: String</code>. Spezialisiert durch <code>BlueprintPolicyModifiable</code> und <code>BlueprintPolicyNotModifiable</code>.\n</li><li><strong>BlueprintPolicyNotModifiable</strong>: Konkrete Ausprägung von <code>BlueprintPolicy</code> zur Festlegung nicht-veränderbarer Vorgaben ohne zusätzliche Attribute.\n</li><li><strong>BlueprintPolicyModifiable</strong>: Abstrakte Spezialisierung von <code>BlueprintPolicy</code> für anpassbare Blueprint-Vorgaben. Besitzt eine Kompositionsbeziehung <code>+blueprintDerivationGuide</code> mit Multiplizität <code>0..1</code> zu <code>DocumentationBlock</code>.\n</li><li><strong>DocumentationBlock</strong>: Dokumentationsbaustein (<code>«atpMixed»</code>) zur textuellen Anleitung der Elementableitung.\n</li><li><strong>BlueprintPolicySingle</strong>: Konkrete Ausprägung von <code>BlueprintPolicyModifiable</code> für singuläre Attribute/Elemente.\n</li><li><strong>BlueprintPolicyList</strong>: Konkrete Ausprägung von <code>BlueprintPolicyModifiable</code> für Listenattribute. Enthält die variablen Attribute <code>+ maxNumberOfElements: PositiveInteger</code> und <code>+ minNumberOfElements: PositiveInteger</code> unter dem Stereotyp <code>«atpVariation»</code>.\n</li><li><strong>Identifiable</strong>: Abstrakte Metaklasse für identifizierbare Elemente.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne dynamische Interaktionen oder Laufzeitsequenzen. Die Modellierungssemantik definiert zur Entwurfs- bzw. Standardisierungszeit die eindeutige Zuordnung (<code>AtpBlueprintMapping</code>) einer konkreten Vorlage (<code>AtpBlueprint</code>) zu einem ausprägenden Artefakt (<code>AtpBlueprintable</code>) innerhalb eines zentral verwalteten Sets (<code>BlueprintMappingSet</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Blueprint-Richtlinien steuern normativ die Freiheitsgrade bei der Ausprägung konkreter Modellelemente aus Blueprints:</p>\n<ul class=\"fig-list\"><li><code>BlueprintPolicyNotModifiable</code> verbietet jegliche Abweichung vom vorgegebenen Attributwert.\n</li><li><code>BlueprintPolicyModifiable</code> erlaubt Anpassungen; über <code>blueprintDerivationGuide</code> (<code>DocumentationBlock</code>, <code>«atpMixed»</code>) kann ein erläuternder Richtlinientext hinterlegt werden.\n</li><li><code>BlueprintPolicyList</code> gestattet die Steuerung von Listenfeldern über Multiplizitätsgrenzen (<code>minNumberOfElements</code>, <code>maxNumberOfElements</code>), die dem Stereotyp <code>«atpVariation»</code> unterliegen und somit variabel gebunden werden können.\n</li><li>Die Adressierung des betroffenen Modellelement-Attributs erfolgt über <code>attributeName: String</code>.\n</li><li><code>+/atpBlueprint</code> und <code>+/atpBlueprintedElement</code> sind abgeleitete Assoziationen, <code>AtpBlueprint</code> ist per kanonischer URI adressierbar (<code>«atpUriDef»</code>).\n</li></ul>"}], "trans": [{"from": "FIG-d541ccf781ab8ab7", "to": "FIG-f52eabb89021ee0c", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>BlueprintMappingSet</strong>: Die vorangestellte Paket- bzw. Namespace-Qualifizierung <code>BlueprintMapping::</code> im Klassennamen wurde entfernt; die Klasse heißt nun direkt <code>BlueprintMappingSet</code>.\n</li></ul>"}, {"from": "FIG-f52eabb89021ee0c", "to": "FIG-77db9281efcebade", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>AtpBlueprint</strong>: Komposition <code>+blueprintPolicy</code> mit Multiplizität <code>0..*</code> zur abstrakten Basisklasse <code>BlueprintPolicy</code> hinzugefügt.\n</li><li><strong>BlueprintPolicy</strong>: Abstrakte Klasse mit Attribut <code>+ attributeName :String</code> neu eingeführt; spezialisiert durch die neuen Subklassen <code>BlueprintPolicyModifiable</code> und <code>BlueprintPolicyNotModifiable</code>.\n</li><li><strong>BlueprintPolicyModifiable</strong>: Abstrakte Klasse zur Definition modifizierbarer Blueprint-Vorgaben eingeführt, spezialisiert durch die konkreten Klassen <code>BlueprintPolicySingle</code> und <code>BlueprintPolicyList</code>.\n</li><li><strong>DocumentationBlock</strong>: Über Komposition <code>+blueprintDerivationGuide</code> mit Multiplizität <code>0..1</code> an <code>BlueprintPolicyModifiable</code> angebunden (Stereotyp <code>«atpMixed»</code>).\n</li><li><strong>BlueprintPolicyList</strong>: Konkrete Spezialisierung von <code>BlueprintPolicyModifiable</code> mit Attributen <code>+ maxNumberOfElements :PositiveInteger</code> und <code>+ minNumberOfElements :PositiveInteger</code> (beide unter Stereotyp <code>«atpVariation»</code>) neu eingeführt.\n</li><li><strong>BlueprintPolicySingle</strong>: Konkrete Spezialisierung von <code>BlueprintPolicyModifiable</code> ohne eigene Attribute neu eingeführt.\n</li></ul>"}, {"from": "FIG-77db9281efcebade", "to": "FIG-1b195e000a209bc1", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-1b195e000a209bc1", "to": "FIG-398e1c7587220dde", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>BlueprintPolicy</strong>: Leerzeichen nach dem Doppelpunkt bei Attributdeklaration ergänzt (<code>+ attributeName: String</code> statt zuvor <code>+ attributeName :String</code>).\n</li><li><strong>BlueprintPolicyList</strong>: Leerzeichen nach den Doppelpunkten bei den Attributdeklarationen ergänzt (<code>+ maxNumberOfElements: PositiveInteger</code>, <code>+ minNumberOfElements: PositiveInteger</code> statt zuvor <code>:PositiveInteger</code>).\n</li></ul>"}, {"from": "FIG-398e1c7587220dde", "to": "FIG-f39c76eaed77697b", "fr": "R21-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
